window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58ec1092fe0db1ff"]={"versions": [{"id": "FIG-58ec1092fe0db1ff", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit verschachtelten Ausführungsrahmen (<code>combined fragments</code> / bedingte Blöcke).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des asynchron entkoppelten Empfangspfades (Decoupled Reception Handling) im AUTOSAR FlexRay Transport Layer (<code>FrTp</code>, ISO 10681-2) gemäß AUTOSAR R4.1.3.</li>\n<li><strong>Architektur-Kontext:</strong> Entkopplung des zeitkritischen Interrupt-/Treiber-Kontexts (<code>FrIf</code>) von der oberen Kommunikationsschicht (<code>PduR</code>). <code>FrTp_RxIndication()</code> puffert empfangene N-PDUs lediglich zwischen; die Weitergabe an den PDU-Router via <code>PduR_StartOfReception()</code> und <code>PduR_FrTpCopyRxData()</code> erfolgt verzögert im periodischen Kontext der <code>FrTp_MainFunction()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Module (Lifelines):</strong></li>\n<li><code>PduR</code> (PDU Router): Vermittlungsschicht; allokiert Empfangspuffer und nimmt assemblierte I-SDUs entgegen.</li>\n<li><code>FrTp</code> (FlexRay ISO Transport Layer): Segmentierung, Reassemblierung, Flusssteuerung und Quittierung gemäß ISO 10681-2.</li>\n<li><code>FrIf</code> (FlexRay Interface): Hardware-Abstraktionsschicht des FlexRay-Kommunikations-Controllers.</li>\n<li><strong>Aufgerufene Schnittstellen & APIs:</strong></li>\n<li><strong>Unterer Schichtenübergang (<code>FrTp</code> $\\leftrightarrow$ <code>FrIf</code>):</strong></li>\n<li><code>FrTp_RxIndication()</code>: Benachrichtigung über eingegangene FlexRay-N-PDU aus dem Bus-Interface.</li>\n<li><code>FrIf_Transmit()</code>: Sendeanforderung für Transportprotokoll-Steuerframes (FC / Ack).</li>\n<li><code>FrTp_TriggerTransmit()</code>: Polling-Callback des <code>FrIf</code> zur Datenübergabe bei entkoppeltem Puffermodus (<em>Decoupled Buffer Access</em>).</li>\n<li><code>FrTp_TxConfirmation()</code>: Sendebestätigung für FC- bzw. Ack-Frames.</li>\n<li><strong>Oberer Schichtenübergang (<code>FrTp</code> $\\rightarrow$ <code>PduR</code>):</strong></li>\n<li><code>PduR_StartOfReception()</code> (bzw. <code>PduR_FrTpStartOfReception()</code>): Initialer Aufruf zur Pufferbereitstellung bei Beginn einer SDU-Rezeption.</li>\n<li><code>PduR_FrTpCopyRxData()</code>: Segmentweises Kopieren empfangener Nutzdaten in den Zielpuffer des PduR/oberen Layers.</li>\n<li><code>PduR_RxIndication()</code>: Finale Abschlussmeldung über die vollständig empfangene I-SDU.</li>\n<li><strong>Zustandsvariablen / Flags:</strong></li>\n<li><code>RX_PDU_AVAILABLE</code>: Synchronisations-Flag zwischen ISR-/Interface-Kontext und periodischem MainFunction-Kontext.</li>\n<li><code>TX_PDU_AVAILABLE</code>: Status-Flag zur Steuerung von Sendeanforderungen (wird bei Abschluss zurückgesetzt).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phasen-Trigger (Interrupt- bzw. Treiber-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>FrIf</code> ruft synchron <code>FrTp_RxIndication()</code> auf.</li>\n<li><code>FrTp</code> kopiert die N-PDU intern (<code>Copy data</code>) und setzt das interne Signal-Flag <code>RX_PDU_AVAILABLE = True</code>.</li>\n<li>Rücksprung zu <code>FrIf</code>. Keine Interaktion mit dem <code>PduR</code> im ISR-Kontext.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Geplante Verarbeitung im Task-Kontext (<code>FrTp_Main</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die periodische <code>FrTp_MainFunction()</code> prüft <code>Check Flag RX_PDU_AVAILABLE</code>.</li>\n<li><strong>Bedingung <code>RX_PDU_AVAILABLE == True</code>:</strong></li>\n<li><strong>Block <code>If SF received</code> (Single Frame):</strong></li>\n<li><code>FrTp</code> ruft <code>PduR_StartOfReception()</code> auf, um den Empfang anzumelden und die Puffergröße zu verifizieren.</li>\n<li><code>FrTp</code> ruft <code>PduR_FrTpCopyRxData()</code> auf; <code>PduR</code> kopiert die Daten in den Zielspeicher.</li>\n<li><strong>Block <code>If N-Pdu.FC or N-Pdu.Ack is required</code>:</strong></li>\n<li>Falls das Protokoll eine Flusssteuerung (Flow Control) oder Quittierung (Ack) erfordert: Aufruf von <code>FrIf_Transmit()</code>.</li>\n<li><em>Optional (<code>If Decoupled Buffer Access is configured</code>):</em> <code>FrIf</code> fordert die Frame-Payload zeitversetzt via Callback <code>FrTp_TriggerTransmit()</code> an.</li>\n<li><code>FrIf</code> bestätigt den Sendevorgang via <code>FrTp_TxConfirmation()</code>.</li>\n<li><strong>Block <code>If complete SDU is received</code>:</strong></li>\n<li><code>FrTp</code> setzt das Sende-/Statusflag zurück (<code>Reset Flag TX_PDU_AVAILABLE</code>).</li>\n<li><code>FrTp</code> signalisiert den erfolgreichen Gesamtempfang an die Anwendung via <code>PduR_RxIndication()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext- und Thread-Sicherheit:</strong> <code>RX_PDU_AVAILABLE</code> fungiert als IPC-Schranke zwischen ISR (<code>FrIf_RxIndication</code>) und OS-Task (<code>FrTp_MainFunction</code>). Der Zugriff muss atomar oder über Critical Sections (<code>SchM_Enter_FrTp_...</code>) abgesichert sein, um Race Conditions zu verhindern.</li>\n<li><strong>Speicher-Overhead:</strong> Das Verfahren erzwingt Zwischenpuffer im <code>FrTp</code> (RAM-Bedarf pro Empfangskanal), da Nutzdaten im <code>RxIndication</code>-Aufruf zwischengespeichert werden müssen, bevor der <code>PduR</code>-Zielpuffer via <code>PduR_StartOfReception()</code> überhaupt angefordert wird.</li>\n<li><strong>Latenz & ISO 10681-2 Timer:</strong> Das Verschieben von <code>PduR_StartOfReception()</code> und der FC/Ack-Generierung in die <code>FrTp_MainFunction()</code> macht die Antwortzeiten direkt abhängig vom Task-Scheduling-Intervall (<code>FrTpMainFunctionCycle</code>). Eine zu große Zykluszeit führt zu Protokoll-Timeouts (Verletzung von $N\\_Ar$ / $N\\_Br$) auf dem FlexRay-Bus.</li>\n<li><strong>Pufferzugriffsmodus:</strong> Der Aufruf von <code>FrTp_TriggerTransmit()</code> ist rein konfigurativ: Er wird nur durchlaufen, wenn im <code>FrIf</code> / <code>Fr</code> der entkoppelte Puffermodus aktiviert ist (<em>im Schaubild als „Decoubled Buffer Access“ typographisch fehlerhaft mit „b“ beschriftet</em>). Im direkten Modus übergibt <code>FrIf_Transmit()</code> den Puffer unmittelbar.</li>\n</ul>"}, {"id": "FIG-034a43c00da32a8f", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit verschachtelten Ausführungsrahmen (<code>combined fragments</code> / bedingte Blöcke).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des asynchron entkoppelten Empfangspfades (Decoupled Reception Handling) im AUTOSAR FlexRay Transport Layer (<code>FrTp</code>, ISO 10681-2) gemäß AUTOSAR R4.1.3.</li>\n<li><strong>Architektur-Kontext:</strong> Entkopplung des zeitkritischen Interrupt-/Treiber-Kontexts (<code>FrIf</code>) von der oberen Kommunikationsschicht (<code>PduR</code>). <code>FrTp_RxIndication()</code> puffert empfangene N-PDUs lediglich zwischen; die Weitergabe an den PDU-Router via <code>PduR_StartOfReception()</code> und <code>PduR_FrTpCopyRxData()</code> erfolgt verzögert im periodischen Kontext der <code>FrTp_MainFunction()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Module (Lifelines):</strong></li>\n<li><code>PduR</code> (PDU Router): Vermittlungsschicht; allokiert Empfangspuffer und nimmt assemblierte I-SDUs entgegen.</li>\n<li><code>FrTp</code> (FlexRay ISO Transport Layer): Segmentierung, Reassemblierung, Flusssteuerung und Quittierung gemäß ISO 10681-2.</li>\n<li><code>FrIf</code> (FlexRay Interface): Hardware-Abstraktionsschicht des FlexRay-Kommunikations-Controllers.</li>\n<li><strong>Aufgerufene Schnittstellen & APIs:</strong></li>\n<li><strong>Unterer Schichtenübergang (<code>FrTp</code> $\\leftrightarrow$ <code>FrIf</code>):</strong></li>\n<li><code>FrTp_RxIndication()</code>: Benachrichtigung über eingegangene FlexRay-N-PDU aus dem Bus-Interface.</li>\n<li><code>FrIf_Transmit()</code>: Sendeanforderung für Transportprotokoll-Steuerframes (FC / Ack).</li>\n<li><code>FrTp_TriggerTransmit()</code>: Polling-Callback des <code>FrIf</code> zur Datenübergabe bei entkoppeltem Puffermodus (<em>Decoupled Buffer Access</em>).</li>\n<li><code>FrTp_TxConfirmation()</code>: Sendebestätigung für FC- bzw. Ack-Frames.</li>\n<li><strong>Oberer Schichtenübergang (<code>FrTp</code> $\\rightarrow$ <code>PduR</code>):</strong></li>\n<li><code>PduR_StartOfReception()</code> (bzw. <code>PduR_FrTpStartOfReception()</code>): Initialer Aufruf zur Pufferbereitstellung bei Beginn einer SDU-Rezeption.</li>\n<li><code>PduR_FrTpCopyRxData()</code>: Segmentweises Kopieren empfangener Nutzdaten in den Zielpuffer des PduR/oberen Layers.</li>\n<li><code>PduR_RxIndication()</code>: Finale Abschlussmeldung über die vollständig empfangene I-SDU.</li>\n<li><strong>Zustandsvariablen / Flags:</strong></li>\n<li><code>RX_PDU_AVAILABLE</code>: Synchronisations-Flag zwischen ISR-/Interface-Kontext und periodischem MainFunction-Kontext.</li>\n<li><code>TX_PDU_AVAILABLE</code>: Status-Flag zur Steuerung von Sendeanforderungen (wird bei Abschluss zurückgesetzt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phasen-Trigger (Interrupt- bzw. Treiber-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>FrIf</code> ruft synchron <code>FrTp_RxIndication()</code> auf.</li>\n<li><code>FrTp</code> kopiert die N-PDU intern (<code>Copy data</code>) und setzt das interne Signal-Flag <code>RX_PDU_AVAILABLE = True</code>.</li>\n<li>Rücksprung zu <code>FrIf</code>. Keine Interaktion mit dem <code>PduR</code> im ISR-Kontext.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Geplante Verarbeitung im Task-Kontext (<code>FrTp_Main</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die periodische <code>FrTp_MainFunction()</code> prüft <code>Check Flag RX_PDU_AVAILABLE</code>.</li>\n<li><strong>Bedingung <code>RX_PDU_AVAILABLE == True</code>:</strong></li>\n<li><strong>Block <code>If SF received</code> (Single Frame):</strong></li>\n<li><code>FrTp</code> ruft <code>PduR_StartOfReception()</code> auf, um den Empfang anzumelden und die Puffergröße zu verifizieren.</li>\n<li><code>FrTp</code> ruft <code>PduR_FrTpCopyRxData()</code> auf; <code>PduR</code> kopiert die Daten in den Zielspeicher.</li>\n<li><strong>Block <code>If N-Pdu.FC or N-Pdu.Ack is required</code>:</strong></li>\n<li>Falls das Protokoll eine Flusssteuerung (Flow Control) oder Quittierung (Ack) erfordert: Aufruf von <code>FrIf_Transmit()</code>.</li>\n<li><em>Optional (<code>If Decoupled Buffer Access is configured</code>):</em> <code>FrIf</code> fordert die Frame-Payload zeitversetzt via Callback <code>FrTp_TriggerTransmit()</code> an.</li>\n<li><code>FrIf</code> bestätigt den Sendevorgang via <code>FrTp_TxConfirmation()</code>.</li>\n<li><strong>Block <code>If complete SDU is received</code>:</strong></li>\n<li><code>FrTp</code> setzt das Sende-/Statusflag zurück (<code>Reset Flag TX_PDU_AVAILABLE</code>).</li>\n<li><code>FrTp</code> signalisiert den erfolgreichen Gesamtempfang an die Anwendung via <code>PduR_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext- und Thread-Sicherheit:</strong> <code>RX_PDU_AVAILABLE</code> fungiert als IPC-Schranke zwischen ISR (<code>FrIf_RxIndication</code>) und OS-Task (<code>FrTp_MainFunction</code>). Der Zugriff muss atomar oder über Critical Sections (<code>SchM_Enter_FrTp_...</code>) abgesichert sein, um Race Conditions zu verhindern.</li>\n<li><strong>Speicher-Overhead:</strong> Das Verfahren erzwingt Zwischenpuffer im <code>FrTp</code> (RAM-Bedarf pro Empfangskanal), da Nutzdaten im <code>RxIndication</code>-Aufruf zwischengespeichert werden müssen, bevor der <code>PduR</code>-Zielpuffer via <code>PduR_StartOfReception()</code> überhaupt angefordert wird.</li>\n<li><strong>Latenz & ISO 10681-2 Timer:</strong> Das Verschieben von <code>PduR_StartOfReception()</code> und der FC/Ack-Generierung in die <code>FrTp_MainFunction()</code> macht die Antwortzeiten direkt abhängig vom Task-Scheduling-Intervall (<code>FrTpMainFunctionCycle</code>). Eine zu große Zykluszeit führt zu Protokoll-Timeouts (Verletzung von $N\\_Ar$ / $N\\_Br$) auf dem FlexRay-Bus.</li>\n<li><strong>Pufferzugriffsmodus:</strong> Der Aufruf von <code>FrTp_TriggerTransmit()</code> ist rein konfigurativ: Er wird nur durchlaufen, wenn im <code>FrIf</code> / <code>Fr</code> der entkoppelte Puffermodus aktiviert ist (<em>im Schaubild als „Decoubled Buffer Access“ typographisch fehlerhaft mit „b“ beschriftet</em>). Im direkten Modus übergibt <code>FrIf_Transmit()</code> den Puffer unmittelbar.</li>\n</ul>"}, {"id": "FIG-db17d51170a83107", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit verschachtelten Ausführungsrahmen (<code>combined fragments</code> / bedingte Blöcke).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des asynchron entkoppelten Empfangspfades (Decoupled Reception Handling) im AUTOSAR FlexRay Transport Layer (<code>FrTp</code>, ISO 10681-2) gemäß AUTOSAR R4.1.3.</li>\n<li><strong>Architektur-Kontext:</strong> Entkopplung des zeitkritischen Interrupt-/Treiber-Kontexts (<code>FrIf</code>) von der oberen Kommunikationsschicht (<code>PduR</code>). <code>FrTp_RxIndication()</code> puffert empfangene N-PDUs lediglich zwischen; die Weitergabe an den PDU-Router via <code>PduR_StartOfReception()</code> und <code>PduR_FrTpCopyRxData()</code> erfolgt verzögert im periodischen Kontext der <code>FrTp_MainFunction()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Module (Lifelines):</strong></li>\n<li><code>PduR</code> (PDU Router): Vermittlungsschicht; allokiert Empfangspuffer und nimmt assemblierte I-SDUs entgegen.</li>\n<li><code>FrTp</code> (FlexRay ISO Transport Layer): Segmentierung, Reassemblierung, Flusssteuerung und Quittierung gemäß ISO 10681-2.</li>\n<li><code>FrIf</code> (FlexRay Interface): Hardware-Abstraktionsschicht des FlexRay-Kommunikations-Controllers.</li>\n<li><strong>Aufgerufene Schnittstellen & APIs:</strong></li>\n<li><strong>Unterer Schichtenübergang (<code>FrTp</code> $\\leftrightarrow$ <code>FrIf</code>):</strong></li>\n<li><code>FrTp_RxIndication()</code>: Benachrichtigung über eingegangene FlexRay-N-PDU aus dem Bus-Interface.</li>\n<li><code>FrIf_Transmit()</code>: Sendeanforderung für Transportprotokoll-Steuerframes (FC / Ack).</li>\n<li><code>FrTp_TriggerTransmit()</code>: Polling-Callback des <code>FrIf</code> zur Datenübergabe bei entkoppeltem Puffermodus (<em>Decoupled Buffer Access</em>).</li>\n<li><code>FrTp_TxConfirmation()</code>: Sendebestätigung für FC- bzw. Ack-Frames.</li>\n<li><strong>Oberer Schichtenübergang (<code>FrTp</code> $\\rightarrow$ <code>PduR</code>):</strong></li>\n<li><code>PduR_StartOfReception()</code> (bzw. <code>PduR_FrTpStartOfReception()</code>): Initialer Aufruf zur Pufferbereitstellung bei Beginn einer SDU-Rezeption.</li>\n<li><code>PduR_FrTpCopyRxData()</code>: Segmentweises Kopieren empfangener Nutzdaten in den Zielpuffer des PduR/oberen Layers.</li>\n<li><code>PduR_RxIndication()</code>: Finale Abschlussmeldung über die vollständig empfangene I-SDU.</li>\n<li><strong>Zustandsvariablen / Flags:</strong></li>\n<li><code>RX_PDU_AVAILABLE</code>: Synchronisations-Flag zwischen ISR-/Interface-Kontext und periodischem MainFunction-Kontext.</li>\n<li><code>TX_PDU_AVAILABLE</code>: Status-Flag zur Steuerung von Sendeanforderungen (wird bei Abschluss zurückgesetzt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Phasen-Trigger (Interrupt- bzw. Treiber-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>FrIf</code> ruft synchron <code>FrTp_RxIndication()</code> auf.</li>\n<li><code>FrTp</code> kopiert die N-PDU intern (<code>Copy data</code>) und setzt das interne Signal-Flag <code>RX_PDU_AVAILABLE = True</code>.</li>\n<li>Rücksprung zu <code>FrIf</code>. Keine Interaktion mit dem <code>PduR</code> im ISR-Kontext.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Geplante Verarbeitung im Task-Kontext (<code>FrTp_Main</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die periodische <code>FrTp_MainFunction()</code> prüft <code>Check Flag RX_PDU_AVAILABLE</code>.</li>\n<li><strong>Bedingung <code>RX_PDU_AVAILABLE == True</code>:</strong></li>\n<li><strong>Block <code>If SF received</code> (Single Frame):</strong></li>\n<li><code>FrTp</code> ruft <code>PduR_StartOfReception()</code> auf, um den Empfang anzumelden und die Puffergröße zu verifizieren.</li>\n<li><code>FrTp</code> ruft <code>PduR_FrTpCopyRxData()</code> auf; <code>PduR</code> kopiert die Daten in den Zielspeicher.</li>\n<li><strong>Block <code>If N-Pdu.FC or N-Pdu.Ack is required</code>:</strong></li>\n<li>Falls das Protokoll eine Flusssteuerung (Flow Control) oder Quittierung (Ack) erfordert: Aufruf von <code>FrIf_Transmit()</code>.</li>\n<li><em>Optional (<code>If Decoupled Buffer Access is configured</code>):</em> <code>FrIf</code> fordert die Frame-Payload zeitversetzt via Callback <code>FrTp_TriggerTransmit()</code> an.</li>\n<li><code>FrIf</code> bestätigt den Sendevorgang via <code>FrTp_TxConfirmation()</code>.</li>\n<li><strong>Block <code>If complete SDU is received</code>:</strong></li>\n<li><code>FrTp</code> setzt das Sende-/Statusflag zurück (<code>Reset Flag TX_PDU_AVAILABLE</code>).</li>\n<li><code>FrTp</code> signalisiert den erfolgreichen Gesamtempfang an die Anwendung via <code>PduR_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext- und Thread-Sicherheit:</strong> <code>RX_PDU_AVAILABLE</code> fungiert als IPC-Schranke zwischen ISR (<code>FrIf_RxIndication</code>) und OS-Task (<code>FrTp_MainFunction</code>). Der Zugriff muss atomar oder über Critical Sections (<code>SchM_Enter_FrTp_...</code>) abgesichert sein, um Race Conditions zu verhindern.</li>\n<li><strong>Speicher-Overhead:</strong> Das Verfahren erzwingt Zwischenpuffer im <code>FrTp</code> (RAM-Bedarf pro Empfangskanal), da Nutzdaten im <code>RxIndication</code>-Aufruf zwischengespeichert werden müssen, bevor der <code>PduR</code>-Zielpuffer via <code>PduR_StartOfReception()</code> überhaupt angefordert wird.</li>\n<li><strong>Latenz & ISO 10681-2 Timer:</strong> Das Verschieben von <code>PduR_StartOfReception()</code> und der FC/Ack-Generierung in die <code>FrTp_MainFunction()</code> macht die Antwortzeiten direkt abhängig vom Task-Scheduling-Intervall (<code>FrTpMainFunctionCycle</code>). Eine zu große Zykluszeit führt zu Protokoll-Timeouts (Verletzung von $N\\_Ar$ / $N\\_Br$) auf dem FlexRay-Bus.</li>\n<li><strong>Pufferzugriffsmodus:</strong> Der Aufruf von <code>FrTp_TriggerTransmit()</code> ist rein konfigurativ: Er wird nur durchlaufen, wenn im <code>FrIf</code> / <code>Fr</code> der entkoppelte Puffermodus aktiviert ist (<em>im Schaubild als „Decoubled Buffer Access“ typographisch fehlerhaft mit „b“ beschriftet</em>). Im direkten Modus übergibt <code>FrIf_Transmit()</code> den Puffer unmittelbar.</li>\n</ul>"}], "trans": [{"from": "FIG-58ec1092fe0db1ff", "to": "FIG-034a43c00da32a8f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-034a43c00da32a8f", "to": "FIG-db17d51170a83107", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
